        int style = java.text.DateFormat.FULL;
        TimeZone timeZone = TimeZone.getTimeZone("GMT");

        // Get the formatter with a null locale
        FastDateFormat formatter = FastDateFormat.getDateInstance(style, timeZone, null);

        // Get the expected pattern using the default locale
        Locale defaultLocale = Locale.getDefault();
